function setup() {
  c = min(windowHeight, windowWidth) * 0.9;
  cnv = createCanvas(c, c);
  randN = int(random(-10, 10));
  randN = int(random() * 100000000);
  n = int(random(80, 120));
  r1 = int(random(170, 285));
  g1 = int(random(170, 285));
  b1 = int(random(170, 285));
  for (let i = 0; i < 4; i++) {
    cArray[i] = color(r1 / (i + 1), g1 / (i + 1), b1 / (i + 1));
  }
  strokeWeight(0.02);
  stroke(cArray[1]);
  noLoop();
  t = 3;
}

function draw() {
  background(cArray[0]);

  push();

  translate(width / 2, width / 2);
  scale(0.9, 0.9);
  if (b1 % 3 === 0) {
    rotate(PI / 2);
  }
  r = width / n;
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      if (j % 2 === 0) {
        x = -width / 2 + r * j * 3;
        y = -width / 2 + r * i * 3.45;
      } else {
        x = -width / 2 + r * j * 3;
        y = -width / 2 + r * i * 3.45 + r * (3.45 / 2);
      }
      variation(v, i, j);
      push();
      translate(x, y);
      hexi(r * 2, c1, c2, s);
      pop();
    }
  }
  fill(cArray[3]);
  rect(-width / 2, -width / 2, width, r);
  rect(-width / 2, -width / 2, r, width);
  rect(width / 2 - r, -width / 2, r, width);
  rect(-width / 2, width / 2 - r, width, r);
  pop();
  rect(0, 0, width, 0.05 * height);
  rect(0, height - 0.05 * height, width, 0.05 * height);
  rect(0, 0, width * 0.05, height);
  rect(width - width * 0.05, 0, width * 0.05, height);
  stroke(100);
  fill(150);
  if (v % 2 === 0) {
    text("Random Quilt v:" + randN, 10, 10);
    text("r:" + r1 + " g:" + g1 + " b:" + b1 + " n:" + n, 10, height - 5);
  } else {
    text("Quilt variation: " + floor(v / 2), 10, 10);
    text("r:" + r1 + " g:" + g1 + " b:" + b1 + " n:" + n, 10, height - 5);
  }
}

function hexi(radius, c1, c2, s) {
  let angle = TWO_PI / 6;
  fill(c1);
  beginShape();
  for (let a = s; a <= s + PI; a += (Math.max(0.001, Math.abs(angle)) || 1)) {
    let sx = cos(a) * radius;
    let sy = sin(a) * radius;
    vertex(sx, sy);
  }
  endShape(CLOSE);
  fill(c2);

  beginShape();
  for (let a = PI + s; a < TWO_PI + s; a += (Math.max(0.001, Math.abs(angle)) || 1)) {
    let sx = cos(a) * radius;
    let sy = sin(a) * radius;
    vertex(sx, sy);
  }
  endShape(CLOSE);
}

